// === Tab: mySketch ===
// Title: Kaleidoscopic Fractal: Polymorphic Echoes (Dynamic Generation Waves)

// This sketch generates a recursive fractal where shapes change per generation and per wave.
// [INCLUDED] Lifecycle logic with Fade In, Visible, White-out, Return to Color, Fade Out, and Blackout phases.
// [MODIFIED] Shapes (3, 4, or 5 sides) are randomized dynamically for each generation's specific cycle.

// --- Global Settings ---
let angle = 0;                    
const rotationSpeed = 0.1;        // Base rotation speed
const maxDepth = 4;               
const hueShiftSpeed = 0.3;        

// --- Loop Settings (Maintained) ---
const fadeInDuration = 5000;      // Phase 1: Fade In
const visibleDuration = 2000;     // Phase 2: Fully Visible
const whiteDuration = 2000;       // Phase 3: Become White (Saturation 100 -> 0)
const visibleDuration2 = 2000;    // Phase 4: Fully Visible Again (Saturation 0 -> 100)
const fadeOutDuration = 5000;     // Phase 5: Fade Out
const blackoutDuration = 1000;    // Phase 6: Blackout (Wait in darkness)
const waveDelay = 5000;           // Delay per generation

// Cycle Calculation
const cycleDuration = (maxDepth * waveDelay) + fadeInDuration + visibleDuration + whiteDuration + visibleDuration2 + fadeOutDuration + blackoutDuration; 

// --- Global Variables ---
let colors;                       
let hueOffset = 0;                

function setup() {
  createCanvas(windowWidth, windowHeight); 
  angleMode(DEGREES);                      
  colorMode(HSB, 360, 100, 100, 1.0); 
  noFill();                                
  background(10, 10, 15, 6);    
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight); 
}

function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing

  // --- Background Logic for Blackout ---
  let globalTime = millis();
  let cyclePos = globalTime % cycleDuration;
  let animationEnd = cycleDuration - blackoutDuration;

  if (cyclePos > animationEnd) {
    background(0, 0, 0, 0.2); 
  } else {
    background(0, 0, 0, 0.0005);
  }

  // --- Update Globals ---
  angle += rotationSpeed;       
  hueOffset += hueShiftSpeed;   

  colors = [
    color((0 + hueOffset) % 360, 100, 100),   
    color((60 + hueOffset) % 360, 100, 100),  
    color((120 + hueOffset) % 360, 100, 100)  
  ];

  translate(width / 2, height / 2); 

  // --- Pre-calculate Geometry ---
  const longerSide = max(width, height);          
  const outermostRadius = (longerSide * 0.55) ;   

  const rCluster = outermostRadius / (1 + 2 / sqrt(3)); 
  const dCluster = outermostRadius - rCluster; 

  // --- Kaleidoscope Loop (4-fold Mirror) ---
  for (let k = 0; k < 12; k++) {
    push(); 
    rotate(k * 30); 
    if (k % 2 === 1) scale(-1, 1); 
    rotate(angle); 

    for (let i = 0; i < 3; i++) {
      const a = i * 120 - 90;           
      const x = dCluster * cos(a);      
      const y = dCluster * sin(a);      

      drawFractal(x, y, rCluster, maxDepth, i, 0);
    }
    pop(); 
  }
}

/**
 * Recursive function to draw the fractal polygons.
 */
function drawFractal(x, y, r, depth, colorIndex, generation) {

  const myLag = generation * waveDelay;
  let globalTime = millis();
  let localTime = globalTime - myLag;

  if (localTime < 0) {
    return; 
  }

  let cyclePosition = localTime % cycleDuration;

  let brightVal = 0; 
  let satVal = 100; 

  // Phase Timing
  const p1_End = fadeInDuration;
  const p2_End = p1_End + visibleDuration;
  const p3_End = p2_End + whiteDuration;
  const p4_End = p3_End + visibleDuration2;
  const p5_End = p4_End + fadeOutDuration;

  // --- Lifecycle Logic ---
  if (cyclePosition < p1_End) {
    brightVal = map(cyclePosition, 0, p1_End, 0, 100);
  } else if (cyclePosition < p2_End) {
    brightVal = 100;
  } else if (cyclePosition < p3_End) {
    brightVal = 100;
    satVal = map(cyclePosition, p2_End, p3_End, 100, 0);
  } else if (cyclePosition < p4_End) {
    brightVal = 100;
    satVal = map(cyclePosition, p3_End, p4_End, 0, 100);
  } else if (cyclePosition < p5_End) {
    brightVal = map(cyclePosition, p4_End, p5_End, 100, 0);
  } else {
    brightVal = 0;
  }

  // --- Drawing ---
  push();                                         
  translate(x, y);                                

  rotate(angle * pow(2, generation));                                  

  let baseColor = colors[colorIndex];
  let c = color(hue(baseColor), satVal, brightVal);

  stroke(c);                                      
  strokeWeight(map(r, 0, width / 3, 0.5, 2));     

  if (brightVal > 0.5) {
    // [MODIFIED] Determine Random Sides per Generation & Cycle
    // 1. Calculate which "Wave Cycle" this specific generation is currently in.
    //    Using localTime means the shape change ripples through generations (Wave Delay).
    let currentWaveCycle = floor(localTime / cycleDuration);

    // 2. Create a pseudo-random seed based on the Cycle and Generation.
    //    This ensures the shape is stable for the duration of the cycle, 
    //    but changes when the next wave starts.
    let seed = (currentWaveCycle * 9999) + (generation * 333);

    // 3. Simple hash function to get a random number 0-1 from the seed
    let rand = abs(sin(seed));

    // 4. Map to integer 3, 4, or 5
    let sides = floor(map(rand, 0, 1, 3, 9)); 

    beginShape();                                 
    for (let k = 0; k < sides; k++) {  
      let vAngle = -90 + k * (360 / sides);
      let vx = r * cos(vAngle);                   
      let vy = r * sin(vAngle);                   
      vertex(vx, vy);                             
    }
    endShape(CLOSE);                              
  }

  // --- Recursion ---
  if (depth > 0) {
    const rInner = r / (1 + 2 / sqrt(3));         
    const dInner = r - rInner;                    

    for (let i = 0; i < 3; i++) {
      const a = i * 120 - 90;                     
      const newX = dInner * cos(a);               
      const newY = dInner * sin(a);               

      drawFractal(newX, newY, rInner, depth - 1, i, generation + 1);
    }
  }

  pop();                                          
}

